"""Random protocol job/batch generator for differential fuzzing (well-typed)."""
import random

NUMERIC = ('time', 'size', 'count')


def gen_domain(rng, max_size=4, max_value=40):
    size = rng.randint(1, max_size)
    return sorted(rng.sample(range(0, max_value), size))


def gen_job(rng, width=None, max_pred=None, max_train=None, big=False):
    F = rng.randint(1, 4 if big else 3)
    K = rng.randint(1, 3)
    types = ['time', 'size', 'count', 'id', 'flag']
    fields = []
    for i in range(F):
        t = rng.choice(types)
        if big:
            dom = gen_domain(rng, max_size=6, max_value=200)
        elif t in ('id', 'flag'):
            dom = gen_domain(rng, max_size=3, max_value=20)
        else:
            dom = gen_domain(rng, max_size=4, max_value=60)
        fields.append({'name': f'f{i}', 'type': t, 'domain': dom})
    by_type = {}
    for f in fields:
        by_type.setdefault(f['type'], []).append(f['name'])
    names = [f['name'] for f in fields]
    dom_of = {f['name']: f['domain'] for f in fields}

    def make_term(rng, T, allow_composite=True):
        options = ['ref']
        if T in NUMERIC and allow_composite:
            options += ['const', 'sum', 'scale']
        else:
            options += ['const']
        pick = rng.choice(options)
        if pick == 'ref':
            return {'ref': [rng.randrange(K), rng.choice(by_type[T])]}
        if pick == 'const':
            return {'const': rng.choice([0, 1, 2, 3, 5, 7, 10, 15, 20, 30, 60, 100, 999]), 'type': T}
        if pick == 'sum':
            cells = [[s, n] for s in range(K) for n in by_type[T]]
            k = rng.randint(1, min(K, len(cells)))
            return {'sum': rng.sample(cells, k)}
        return {'scale': rng.choice([0, 1, 2, 3, 7, 100, 65535]),
                'ref': [rng.randrange(K), rng.choice(by_type[T])]}

    preds = []
    P = rng.randint(1, max_pred or (8 if big else 7))
    for _ in range(P):
        kind = rng.choice(['cmp', 'cmp', 'cmp', 'any', 'all'])
        if kind == 'cmp':
            T = rng.choice(types)
            if T not in by_type:
                T = rng.choice(list(by_type))
            ops = ['eq', 'ne'] if T in ('id', 'flag') else ['eq', 'ne', 'lt', 'le', 'gt', 'ge']
            preds.append({'kind': 'cmp', 'left': make_term(rng, T), 'op': rng.choice(ops),
                          'right': make_term(rng, T)})
        else:
            f = rng.choice(fields)
            ops = ['eq', 'ne'] if f['type'] in ('id', 'flag') else ['eq', 'ne', 'lt', 'le', 'gt', 'ge']
            value = rng.choice(f['domain'] + [0, 1, 2, 3, 7, 15, 30, 60, 100])
            preds.append({'kind': kind, 'field': f['name'], 'op': rng.choice(ops), 'value': value})

    if width is None:
        width = rng.randint(1, 4)
    U = 1
    for _ in range(K):
        for f in fields:
            U *= len(f['domain'])
    n_train = rng.randint(1, max(1, min(max_train or (U if big else 20), U)))
    train = []
    for _ in range(n_train):
        train.append([[rng.choice(f['domain']) for f in fields] for _ in range(K)])
    if rng.random() < 0.3 and train:
        train.append([row[:] for row in train[rng.randrange(len(train))]])

    approved = []
    seen = set()
    for _ in range(rng.randint(0, 8)):
        size = rng.randint(1, min(width, max(1, len(preds))))
        if size > len(preds):
            continue
        clause = tuple(sorted(rng.sample(range(len(preds)), size)))
        if clause in seen:
            continue
        seen.add(clause)
        approved.append(list(clause))

    queries = []
    for _ in range(rng.randint(1, 6 if not big else 10)):
        tslot = rng.randrange(K)
        tname = rng.choice(names)
        others = [(s, n) for s in range(K) for n in names if (s, n) != (tslot, tname)]
        fixed = []
        if others and rng.random() < 0.7:
            for s, n in rng.sample(others, rng.randint(1, min(3, len(others)))):
                fixed.append({'ref': [s, n], 'value': rng.choice(dom_of[n])})
        style = rng.random()
        if style < 0.25:
            prefix = ''
        elif style < 0.5:
            prefix = str(rng.choice(dom_of[tname]))
        elif style < 0.75:
            prefix = rng.choice(['0', '00', '01', '1', '10', '2', '9', '007', '1000000',
                                 '99', '0000000', str(rng.randrange(1000))])
        else:
            prefix = ''.join(rng.choice('0123456789') for _ in range(rng.randint(1, 7)))
        queries.append({'target': [tslot, tname], 'prefix': prefix, 'fixed': fixed})

    return {'fields': fields, 'slots': K, 'predicates': preds, 'width': width,
            'train': train, 'approved': approved, 'queries': queries}


def gen_batch(rng, jobs=None, **kw):
    if jobs is None:
        jobs = rng.randint(1, 3)
    return {'jobs': [gen_job(rng, **kw) for _ in range(jobs)]}
