"""Differential fuzzing: exact pipeline vs naive reference."""
import ctypes
import json
import random
import sys
import time

ctypes.CDLL('/workspace/vendor/system-libs/libz.so.1', mode=ctypes.RTLD_GLOBAL)
sys.path.insert(0, '/workspace/vendor')
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/dev')

from brute import brute_batch
from gen import gen_batch
from netnomos.finite import compile_batch


def run(cases, seed0=0, verbose=False):
    bad = 0
    for i in range(cases):
        rng = random.Random(seed0 + i)
        batch = gen_batch(rng)
        want = brute_batch(batch)
        got = compile_batch(batch)
        if got != want:
            bad += 1
            print('MISMATCH seed', seed0 + i)
            print(json.dumps(batch))
            for a, b in zip(got['results'], want['results']):
                if a != b:
                    for key in ('rules', 'active', 'answers'):
                        if a[key] != b[key]:
                            print(' key', key)
                            print('  got ', json.dumps(a[key])[:1500])
                            print('  want', json.dumps(b[key])[:1500])
            if bad >= 2:
                break
    print('done', cases, 'cases, mismatches:', bad)
    return bad


if __name__ == '__main__':
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    t = time.time()
    sys.exit(1 if run(n, seed) else 0)
